insert into public.videos (id, chapter_id, title, description, duration_seconds, thumbnail_url, source_url, notes_url, is_free, view_count, sort) values
  ('59a48cdc-8219-4b57-b263-651aecebb3d3', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'Arithmetic and Geometric Sequences', 'Defines sequences by formula and by recursion, and derives the nth term of arithmetic and geometric sequences with worked examples.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 4605, 1),
  ('a0886d04-96dc-45d3-812b-5c328c61d2b5', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'Sums of Arithmetic and Geometric Series', 'Introduces sigma notation and the sum formulas for finite arithmetic and geometric series, applied to savings and population problems.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 871, 2),
  ('0e7cb44e-8a4d-4ba5-9b3f-6a2207eedf93', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'Infinite Geometric Series', 'Explains when an infinite geometric series converges, finds its sum with S = a/(1 − r), and converts repeating decimals to fractions.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 1120, 3),
  ('ce1b8d93-fe35-45a3-b01e-7d0bff59ce68', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'Limits and Continuity', 'Evaluates limits by substitution, factorization and rationalization, finds limits at infinity, and tests whether a function is continuous at a point.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 4255, 1),
  ('56b20035-840e-4ccd-beeb-0c06910bac2f', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'Derivatives and Their Applications', 'Introduces the derivative as the limit of a difference quotient, applies the power, product, quotient and chain rules, and uses derivatives to solve maximum and minimum problems.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 3100, 2),
  ('8b8f7390-390a-44b5-903f-d472c0a07893', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'Antiderivatives and Definite Integrals', 'Finds antiderivatives of polynomial functions, evaluates definite integrals with the Fundamental Theorem of Calculus, and calculates areas under curves.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 765, 3),
  ('b93244e1-61ec-48e3-a7a4-0ce556295014', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'Graphing Systems of Linear Inequalities', 'Shows how to graph linear inequalities in two variables and identify the feasible region defined by a system of constraints.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 775, 1),
  ('84e1b452-6f44-42d9-b58c-00534a24b52b', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'Formulating Linear Programming Problems', 'Translates word problems about production, diet and farming into decision variables, an objective function and constraints.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 4259, 2),
  ('32045fd6-f408-4e7d-a47e-e4e9eb0a31b9', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'Solving LP Problems by the Corner-Point Method', 'Finds the corner points of bounded and unbounded feasible regions and evaluates the objective function at each to locate the maximum or minimum.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 2854, 3),
  ('8a762a76-5e55-4f32-9810-2ecc7de32496', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Reading for Main Ideas: Community Conservation', 'Practises identifying main ideas, supporting details and the writer''s purpose in a text about Ethiopian communities balancing conservation and economic growth.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 198, 1),
  ('1f697015-a2ca-4947-a2a4-e0109cdc4667', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Vocabulary in Context and Word Forms', 'Builds exam vocabulary by working out meanings from context, finding synonyms and antonyms, and choosing the correct word form.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 409, 2),
  ('8f8c6931-88f8-4138-bb05-858a2f29e8df', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Comparing and Contrasting Devices and Sentence Fragments', 'Uses linkers such as whereas, however, similarly and in contrast to write cohesive paragraphs, and shows how to correct sentence fragments.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 2975, 3),
  ('4ae39151-f8e0-467d-90e2-0bafa0ecde11', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Listening and Reading: Beating Procrastination', 'Develops note-taking and reading for detail using texts on why people procrastinate and practical strategies for managing study time.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 4562, 1),
  ('5481279a-4d62-4e5a-8df3-c7245bb53c0f', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Expressing Result and Making Wishes', 'Covers so…that, such…that, therefore and as a result, and wish structures for present situations and past regrets.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 3762, 2),
  ('14f59864-8d76-401b-b032-a2c2ddacc3b6', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Phrasal Verbs and Word Analogies', 'Practises common phrasal verbs such as put off, catch up and run out of, and solves analogy items of the type found in the national exam.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 470, 3),
  ('c7bd4fb7-4eb2-4a9f-8c7c-ce07e70397d6', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Listening: Retelling an Accident Report', 'Practises listening for sequence and key details in a traffic police report and retelling the incident in the correct order.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 665, 1),
  ('ff61c705-63f8-45f6-bd10-8035975e2e5b', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Narrative Tenses and the Passive Voice', 'Reviews the past simple, past continuous and past perfect for telling stories, and the passive forms used in reports and news.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 3079, 2),
  ('ada60c44-ee1f-4c65-bb4e-8e6372a98645', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Writing a Narrative Essay', 'Plans and drafts a narrative essay with a clear opening, events sequenced with time connectors, and a reflective conclusion.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 918, 3),
  ('a6a5daac-9712-4021-b9b7-647cc07a0c19', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'Projectile Motion', 'Treats horizontal and vertical motion independently to find the time of flight, maximum height and range of projectiles.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 3437, 1),
  ('9f734c34-c8fc-468e-91b5-9f4f46564df9', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'Uniform Circular Motion and Rotational Dynamics', 'Covers angular velocity, centripetal acceleration and force, torque, moment of inertia and conservation of angular momentum.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 1950, 2),
  ('dcf6dfe9-1650-49c9-9d9b-cefcb189f51a', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'Gravitation and Planetary Motion', 'Applies Newton''s law of universal gravitation and Kepler''s laws to planets and satellites, including orbital speed and period.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 1046, 3),
  ('fe994999-292f-4511-a288-36d094af6802', '7e60f676-b178-4409-8644-04c21268ad31', 'Pressure in Fluids and Pascal''s Principle', 'Derives P = ρgh, distinguishes absolute and gauge pressure, and applies Pascal''s principle to hydraulic lifts and brakes.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 2772, 1),
  ('08ef7309-5056-4c33-a403-6a4bc45a96e0', '7e60f676-b178-4409-8644-04c21268ad31', 'Archimedes'' Principle and Flotation', 'Explains buoyant force and why objects float or sink, and shows how to find the density of a solid and the submerged fraction of a floating body.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 3610, 2),
  ('d2067e64-c188-4b77-9917-5017ccb24d0a', '7e60f676-b178-4409-8644-04c21268ad31', 'Fluid Flow: Continuity and Bernoulli''s Equation', 'Uses the continuity equation and Bernoulli''s equation to analyse flow in pipes, aeroplane lift and safety in high-pressure systems.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1478, 3),
  ('a67097b7-060f-45d4-b6e6-2b4bd01f1d7c', '5a75ce5a-97fc-434f-978e-261af116085d', 'Magnetic Fields and Magnetic Forces', 'Describes magnetic field lines and calculates the force on a moving charge (F = qvB sin θ) and on a current-carrying wire (F = BIL sin θ).', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 996, 1),
  ('0f43cdc5-7d94-4a26-a583-31e60c99585c', '5a75ce5a-97fc-434f-978e-261af116085d', 'Electromagnetic Induction: Faraday''s and Lenz''s Laws', 'Explains magnetic flux, induced emf, Faraday''s law and Lenz''s law, and how generators at hydroelectric dams produce electricity.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 1783, 2),
  ('6249e00e-561e-4ef2-acea-d67cc4a889f3', '5a75ce5a-97fc-434f-978e-261af116085d', 'Transformers and Power Transmission', 'Derives the transformer equation, compares step-up and step-down transformers, and shows why power is transmitted at high voltage to reduce losses.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 1956, 3),
  ('c8b7b4dd-b6fa-45e4-9e85-a24f0483d941', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'Arrhenius, Brønsted–Lowry and Lewis Concepts', 'Compares the three definitions of acids and bases and identifies conjugate acid–base pairs in reactions.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 557, 1),
  ('c9519568-80d2-4d74-b100-383b32528c07', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'pH Calculations for Strong and Weak Acids and Bases', 'Uses Kw, Ka and Kb to calculate pH, pOH and percent ionization for solutions of strong and weak acids and bases.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 3216, 2),
  ('4f5882b5-8f79-40cf-87e3-1e0d68ab60d8', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'Buffers, Salt Hydrolysis and Titrations', 'Explains how buffers resist pH change, predicts whether salt solutions are acidic, basic or neutral, and interprets titration curves and the choice of indicator.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 3938, 3),
  ('ec593661-eabe-4f40-b631-eec979577b14', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'Oxidation Numbers and Balancing Redox Equations', 'Assigns oxidation numbers, identifies oxidizing and reducing agents, and balances redox equations by the half-reaction method.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 310, 1),
  ('0b466104-e20a-442e-8af3-383c2e6097c2', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'Galvanic Cells and Standard Electrode Potentials', 'Shows how galvanic cells produce electricity, calculates standard cell potentials from reduction potentials, and predicts whether reactions are spontaneous.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 462, 2),
  ('4a83ecc2-3085-4ef3-9036-6b85684f639e', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'Electrolysis and Faraday''s Laws', 'Describes the electrolysis of molten and aqueous electrolytes, applies Faraday''s laws to calculate the amounts deposited, and covers electroplating and refining.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 4257, 3),
  ('ab86709f-20a5-4195-8830-5db404c8f835', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'Natural Resources and Raw Materials for Industry', 'Surveys Ethiopia''s mineral and agricultural raw materials, such as limestone, potash and sugarcane, and what makes an industrial process economical.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 2098, 1),
  ('1d5bd79a-8dd5-4757-97b1-8021c5a9a8bf', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'Manufacture of Ammonia, Nitric Acid and Sulfuric Acid', 'Explains the Haber, Ostwald and Contact processes, including how temperature, pressure and catalysts are chosen to balance yield, rate and cost.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 1123, 2),
  ('5140df10-b063-45f7-9f05-4d06520a2911', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'Cement, Glass, Sugar and Paper Industries', 'Describes the raw materials and main steps in producing cement, glass, sugar and paper, with examples from Ethiopian factories.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 2171, 3),
  ('d6d0b9ce-dfa9-49ea-8c6c-026354c08c21', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'Bacteria: Structure, Growth and Reproduction', 'Describes prokaryotic cell structure, bacterial shapes, Gram staining and reproduction by binary fission.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 3686, 1),
  ('103a61e9-4c01-4c2d-9b1e-3a506e105ab2', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'Viruses, Fungi and Protozoa', 'Compares the structure and reproduction of viruses, fungi and protozoa, and explains why viruses are not considered living cells.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 2144, 2),
  ('74a14163-df5c-42a4-a36a-8042cfbadd79', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'Microorganisms in Health, Food and Agriculture', 'Explores microbes that cause diseases such as malaria and tuberculosis, and useful microbes that ferment injera and yoghurt, make vaccines and fix nitrogen.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4193, 3),
  ('7a3a3711-0b2d-4cbd-ac37-e810be37d24f', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'ATP and the Light-Dependent Reactions', 'Explains the role of ATP and the structure of the chloroplast, and shows how light energy splits water to produce ATP, NADPH and oxygen.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 838, 1),
  ('7e6cf362-7d75-4c0d-b8dc-5f540ecdaf2f', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'The Calvin Cycle and Limiting Factors', 'Follows carbon fixation by RuBisCO in the Calvin cycle, compares C3 and C4 plants, and examines how light, CO₂ and temperature limit photosynthesis.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 4073, 2),
  ('c57045fb-b3a0-44c1-a4fc-4b90e504afde', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'Cellular Respiration and Fermentation', 'Traces glycolysis, the Krebs cycle and the electron transport chain, and compares aerobic respiration with lactic acid and alcoholic fermentation.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 4180, 3),
  ('366cf004-4eb6-4b02-950e-0af745aa4bc6', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'Theories of Evolution: Lamarck and Darwin', 'Compares Lamarck''s inheritance of acquired characteristics with Darwin''s theory of natural selection and explains why Darwin''s theory is accepted.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 3123, 1),
  ('8edfc8c4-8049-4791-8bcf-e2492cf6f574', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'Evidence for Evolution', 'Examines fossil, anatomical, embryological and molecular evidence, including homologous and analogous structures and the Lucy fossil from Ethiopia''s Afar region.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1995, 2),
  ('f1ba9114-3a1f-48f1-8a63-befc00c9766d', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'Natural Selection and Speciation', 'Explains directional, stabilizing and balancing selection, and how geographical and reproductive isolation lead to the formation of new species.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 2312, 3)
insert into public.questions (id, subject_id, chapter_id, stem, options, correct_option, explanation, difficulty, is_free, sort) values
  ('57927a8c-b417-4487-90e4-0edb633338be', '989f75a8-17b8-41df-9e3d-a993a59946cb', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'What is the 20th term of the arithmetic sequence 5, 8, 11, 14, …?', '[{"key":"A","text":"60"},{"key":"B","text":"65"},{"key":"C","text":"62"},{"key":"D","text":"57"}]'::jsonb, 'C', 'Here a₁ = 5 and d = 3, so a₂₀ = a₁ + (20 − 1)d = 5 + 19 × 3 = 62.', 1, true, 1),
  ('95052b34-4e8e-47c9-87b3-76f9d941e85d', '989f75a8-17b8-41df-9e3d-a993a59946cb', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'Liya saves 50 birr in the first week, 70 birr in the second week and 90 birr in the third week, increasing her savings by 20 birr every week. How much will she have saved in total after 12 weeks?', '[{"key":"A","text":"270 birr"},{"key":"B","text":"1,920 birr"},{"key":"C","text":"1,650 birr"},{"key":"D","text":"3,240 birr"}]'::jsonb, 'B', 'The weekly savings form an arithmetic sequence with a₁ = 50 and d = 20. S₁₂ = (12/2)[2(50) + (12 − 1)(20)] = 6 × 320 = 1,920 birr.', 2, true, 2),
  ('950206f3-3a91-4f91-bf70-c15bb20f4cab', '989f75a8-17b8-41df-9e3d-a993a59946cb', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'In a geometric sequence, the second term is 6 and the fifth term is 162. What is the common ratio?', '[{"key":"A","text":"3"},{"key":"B","text":"2"},{"key":"C","text":"9"},{"key":"D","text":"27"}]'::jsonb, 'A', 'a₅ ÷ a₂ = ar⁴ ÷ ar = r³ = 162 ÷ 6 = 27, so r = 3 (and the first term is 2).', 2, true, 3),
  ('f16a966c-a00c-4471-8390-e7ec7af4147f', '989f75a8-17b8-41df-9e3d-a993a59946cb', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'Which fraction is equal to the repeating decimal 0.272727…?', '[{"key":"A","text":"27/100"},{"key":"B","text":"27/90"},{"key":"C","text":"2/7"},{"key":"D","text":"3/11"}]'::jsonb, 'D', '0.2727… = 27/100 + 27/10,000 + … is an infinite geometric series with a = 27/100 and r = 1/100. Its sum is (27/100) ÷ (1 − 1/100) = 27/99 = 3/11.', 2, true, 4),
  ('2b361f54-1973-4029-a14c-fad9d4f7b98c', '989f75a8-17b8-41df-9e3d-a993a59946cb', '98f70f3a-2202-4eca-a362-f9ff28f6bac3', 'The sum of the first n terms of a sequence is Sₙ = n² + 2n. What is the 10th term of the sequence?', '[{"key":"A","text":"19"},{"key":"B","text":"23"},{"key":"C","text":"21"},{"key":"D","text":"120"}]'::jsonb, 'C', 'a₁₀ = S₁₀ − S₉ = (10² + 2 × 10) − (9² + 2 × 9) = 120 − 99 = 21. In general aₙ = Sₙ − Sₙ₋₁ = 2n + 1.', 3, true, 5),
  ('6fe5e99c-3ce7-4322-90d2-f3428bcd4d9a', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'Evaluate lim (x → 3) (x² − 9)/(x − 3).', '[{"key":"A","text":"0"},{"key":"B","text":"6"},{"key":"C","text":"3"},{"key":"D","text":"Does not exist"}]'::jsonb, 'B', 'Direct substitution gives 0/0, so factorize: (x² − 9)/(x − 3) = (x − 3)(x + 3)/(x − 3) = x + 3 for x ≠ 3. The limit is 3 + 3 = 6.', 1, false, 1),
  ('606b2f13-06c7-4a59-bc44-4cbf2204853f', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'Evaluate lim (x → ∞) (3x² − 5x + 1)/(6x² + 4).', '[{"key":"A","text":"1/2"},{"key":"B","text":"0"},{"key":"C","text":"3"},{"key":"D","text":"∞"}]'::jsonb, 'A', 'Divide the numerator and denominator by x² to get (3 − 5/x + 1/x²)/(6 + 4/x²). As x → ∞ the terms with x in the denominator tend to 0, so the limit is 3/6 = 1/2.', 2, false, 2),
  ('f2daa29b-8dd5-4feb-85b5-701be5485ec8', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'If f(x) = (2x + 1)³, what is f′(1)?', '[{"key":"A","text":"27"},{"key":"B","text":"18"},{"key":"C","text":"9"},{"key":"D","text":"54"}]'::jsonb, 'D', 'By the chain rule, f′(x) = 3(2x + 1)² × 2 = 6(2x + 1)². At x = 1, f′(1) = 6 × 3² = 54.', 2, false, 3),
  ('d7d01f98-4760-4b52-847f-7f2dea3369e1', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'A farmer beside the Awash River has 200 m of fencing to enclose a rectangular field. No fence is needed along the river bank. What is the largest area he can enclose?', '[{"key":"A","text":"2,500 m²"},{"key":"B","text":"4,800 m²"},{"key":"C","text":"5,000 m²"},{"key":"D","text":"10,000 m²"}]'::jsonb, 'C', 'Let x be each side perpendicular to the river, so the side parallel to it is 200 − 2x and A = x(200 − 2x) = 200x − 2x². A′(x) = 200 − 4x = 0 gives x = 50 m, so A = 50 × 100 = 5,000 m² (A″ = −4 < 0 confirms a maximum).', 3, false, 4),
  ('2af18275-3851-41b8-8e7c-54ec3ba95580', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'b2b07421-c209-4b17-916b-5831d4fe21de', 'What is the area of the region bounded by the curve y = 4 − x² and the x-axis?', '[{"key":"A","text":"16/3"},{"key":"B","text":"32/3"},{"key":"C","text":"8"},{"key":"D","text":"64/3"}]'::jsonb, 'B', 'The curve meets the x-axis at x = −2 and x = 2 and lies above it in between. Area = ∫ (4 − x²) dx from −2 to 2 = [4x − x³/3] from −2 to 2 = (8 − 8/3) − (−8 + 8/3) = 32/3 square units.', 3, false, 5),
  ('7731c953-5850-49cd-8153-bcc748953039', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'Which point satisfies the inequality 2x + 3y ≤ 12?', '[{"key":"A","text":"(3, 3)"},{"key":"B","text":"(6, 1)"},{"key":"C","text":"(0, 5)"},{"key":"D","text":"(2, 2)"}]'::jsonb, 'D', 'Substitute each point: (2, 2) gives 2(2) + 3(2) = 10 ≤ 12, so it satisfies the inequality. The other three points each give 15, which is greater than 12.', 1, false, 1),
  ('6dd90945-a274-4183-917c-bc7bc71eb791', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'A small furniture workshop makes chairs and tables. Each chair needs 2 hours of labour and each table needs 5 hours, and at most 40 hours of labour are available per week. If x is the number of chairs and y the number of tables made per week, which inequality represents the labour constraint?', '[{"key":"A","text":"5x + 2y ≤ 40"},{"key":"B","text":"2x + 5y ≤ 40"},{"key":"C","text":"2x + 5y ≥ 40"},{"key":"D","text":"x + y ≤ 40"}]'::jsonb, 'B', 'Chairs use 2x hours and tables use 5y hours, and together they cannot exceed the 40 hours available, so 2x + 5y ≤ 40.', 2, false, 2),
  ('4f391c96-8d14-4d76-bc48-778dfc1a5a4d', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'Maximize Z = 3x + 2y subject to x + y ≤ 4, x + 3y ≤ 6, x ≥ 0 and y ≥ 0. What is the maximum value of Z?', '[{"key":"A","text":"12"},{"key":"B","text":"11"},{"key":"C","text":"4"},{"key":"D","text":"18"}]'::jsonb, 'A', 'The corner points of the feasible region are (0, 0), (4, 0), (3, 1) and (0, 2), where (3, 1) solves x + y = 4 and x + 3y = 6. Z takes the values 0, 12, 11 and 4 there, so the maximum is Z = 12 at (4, 0).', 2, false, 3),
  ('8b05ba6d-1841-4eed-877b-9e18113ef698', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'Minimize C = 2x + 3y subject to x + y ≥ 5, x + 2y ≥ 6, x ≥ 0 and y ≥ 0. What is the minimum value of C?', '[{"key":"A","text":"15"},{"key":"B","text":"12"},{"key":"C","text":"11"},{"key":"D","text":"10"}]'::jsonb, 'C', 'The feasible region is unbounded with corner points (0, 5), (4, 1) and (6, 0), where (4, 1) solves x + y = 5 and x + 2y = 6. C equals 15, 11 and 12 at these points and only increases further from the origin, so the minimum is C = 11 at (4, 1).', 3, false, 4),
  ('3d480c08-1809-4aae-85a8-c4de43bee556', '989f75a8-17b8-41df-9e3d-a993a59946cb', 'f1f80589-db28-4afb-ac24-4ff1e5cf6f40', 'A farmer in Gojjam has 10 hectares of land to plant with teff and maize. Teff needs 3 days of labour per hectare and maize needs 2 days per hectare, and at most 24 labour days are available. The profit is 4,000 birr per hectare of teff and 3,000 birr per hectare of maize. How many hectares of teff should he plant to maximize profit?', '[{"key":"A","text":"6 hectares"},{"key":"B","text":"8 hectares"},{"key":"C","text":"10 hectares"},{"key":"D","text":"4 hectares"}]'::jsonb, 'D', 'With x hectares of teff and y of maize: x + y ≤ 10, 3x + 2y ≤ 24, x ≥ 0, y ≥ 0. The corner points (0, 0), (8, 0), (4, 6) and (0, 10) give profits of 0, 32,000, 34,000 and 30,000 birr, so he should plant 4 ha of teff (and 6 ha of maize).', 3, false, 5),
  ('02724f9a-aa76-420e-a016-d939f70c1295', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Choose the correct form of the word to complete the definition: ''Sustainable development meets the needs of the present without ______ the ability of future generations to meet their own needs.''', '[{"key":"A","text":"compromise"},{"key":"B","text":"compromising"},{"key":"C","text":"compromised"},{"key":"D","text":"to compromise"}]'::jsonb, 'B', 'After a preposition such as ''without'', English uses the gerund (-ing form), so ''without compromising'' is correct. This is the well-known Brundtland Commission definition of sustainable development.', 1, true, 1),
  ('97f1ddf8-837e-4d1a-a095-330f8cbefdaf', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Choose the best linking word: ''Fossil fuels are cheap in the short term; ______, they cause serious long-term damage to the environment.''', '[{"key":"A","text":"however"},{"key":"B","text":"therefore"},{"key":"C","text":"similarly"},{"key":"D","text":"for example"}]'::jsonb, 'A', 'The two clauses present opposing ideas (cheap now, harmful later), so a contrast linker is needed. ''However'' shows contrast, whereas ''therefore'' shows result, ''similarly'' shows comparison and ''for example'' introduces an example.', 2, true, 2),
  ('f4cdc271-7675-44f2-9948-ebbfdb7c5e3b', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Which of the following is a sentence fragment?', '[{"key":"A","text":"Many farmers now use terraces to stop soil erosion."},{"key":"B","text":"The new dam supplies electricity to thousands of homes."},{"key":"C","text":"Recycling reduces waste."},{"key":"D","text":"Because the community planted trees on the hillside."}]'::jsonb, 'D', '''Because the community planted trees on the hillside'' begins with the subordinating conjunction ''because'', so it is a dependent clause that cannot stand alone as a complete thought. Each of the other options has a subject and a finite verb and makes complete sense.', 2, true, 3),
  ('7ec0dab8-2470-4a1f-85e2-d0f8088ac510', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Read the passage and answer the question. ''Over the past two decades, communities in parts of the Ethiopian highlands have restored bare hillsides by closing them to livestock and building stone terraces. Within a few years, grass and trees returned, some dried-up springs began to flow again, and nearby farmers harvested more. Yet these gains were not automatic. Where residents had helped plan the work and shared in its benefits, the enclosures were protected; where projects were imposed from outside, fences were soon broken and the land was degraded again.'' Which statement best expresses the main idea of the passage?', '[{"key":"A","text":"Stone terraces are the only way to increase crop yields."},{"key":"B","text":"Restoring hillsides brings benefits, but lasting success depends on community participation."},{"key":"C","text":"Livestock should be banned from all hillsides in Ethiopia."},{"key":"D","text":"Outside organizations protect land better than local people do."}]'::jsonb, 'B', 'The passage first lists the benefits of restoration and then, after ''Yet'', explains that the results lasted only where residents helped plan the work and shared its benefits. The other options overstate the passage or contradict it.', 3, true, 4),
  ('44671fde-45f5-4ba3-b889-a234c4292f7c', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '5a3f9cc8-d7ba-4631-a600-6334c926e28b', 'Choose the word OPPOSITE in meaning to ''depleted'' in the sentence: ''Years of overuse have depleted the town''s underground water supply.''', '[{"key":"A","text":"exhausted"},{"key":"B","text":"polluted"},{"key":"C","text":"replenished"},{"key":"D","text":"diverted"}]'::jsonb, 'C', '''Depleted'' means used up or greatly reduced, so its opposite is ''replenished'' (filled up again). ''Exhausted'' is a synonym, while ''polluted'' and ''diverted'' have unrelated meanings.', 2, true, 5),
  ('c433dacd-5406-471b-af0e-1ac3e2a98c02', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Choose the phrasal verb that best completes the sentence: ''Hana kept ______ her assignment until the night before the deadline, so she had to rush.''', '[{"key":"A","text":"putting up"},{"key":"B","text":"taking after"},{"key":"C","text":"putting off"},{"key":"D","text":"looking into"}]'::jsonb, 'C', '''Put off'' means to postpone, which fits a student who delays her assignment until the last night. ''Put up'' means to raise or give someone a place to stay, ''take after'' means resemble, and ''look into'' means investigate.', 1, false, 1),
  ('2dc6cbde-4dc2-40ce-a3bb-9125a6228f33', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Dawit failed his exam because he did not plan his study time. Which sentence correctly expresses his regret about the past?', '[{"key":"A","text":"I wish I planned my study time better."},{"key":"B","text":"I wish I would plan my study time better."},{"key":"C","text":"I wish I have planned my study time better."},{"key":"D","text":"I wish I had planned my study time better."}]'::jsonb, 'D', 'A regret about the past is expressed with wish + past perfect: ''I wish I had planned…''. ''I wish I planned'' refers to the present, ''I wish I would'' is not used for one''s own past actions, and ''wish'' is not followed by the present perfect.', 2, false, 2),
  ('6cf91f3c-8e4f-42f9-aeb8-d1b33742cc43', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Choose the correct word: ''It was ______ a busy week that Meron could not finish her project on time.''', '[{"key":"A","text":"such"},{"key":"B","text":"so"},{"key":"C","text":"too"},{"key":"D","text":"very"}]'::jsonb, 'A', '''Such'' is used before a noun phrase (a busy week), whereas ''so'' is used before an adjective or adverb alone (so busy). The pattern such + a + adjective + noun + that expresses a result.', 2, false, 3),
  ('4a16ef95-19d1-47ee-b5d2-693db48e7805', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Choose the word that completes the analogy. CLOCK : TIME :: SCALE : ______', '[{"key":"A","text":"kilogram"},{"key":"B","text":"weight"},{"key":"C","text":"balance"},{"key":"D","text":"kitchen"}]'::jsonb, 'B', 'A clock is an instrument that measures time, so the matching relationship is that a scale measures weight. ''Kilogram'' is a unit rather than the quantity measured, and ''balance'' is another measuring instrument.', 1, false, 4),
  ('3f6f5938-3cdd-408e-a3df-3fc82801415a', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '516155d4-63be-4736-9e24-05728b3bbbc2', 'Read the passage and answer the question. ''In one study, students were asked to estimate how long their final-year projects would take. On average they predicted 34 days; in reality they needed 56. Even their worst-case estimates were too optimistic. Psychologists call this the planning fallacy: we imagine how a task will go if everything runs smoothly and ignore the delays we have met before.'' Which advice would the writer most likely give a student planning a project?', '[{"key":"A","text":"Base your estimate on how long similar tasks actually took in the past."},{"key":"B","text":"Assume that everything will go smoothly so that you stay motivated."},{"key":"C","text":"Avoid making time estimates, since they are always wrong."},{"key":"D","text":"Choose only projects that can be finished in less than 34 days."}]'::jsonb, 'A', 'The passage explains that people underestimate time because they picture an ideal process and ignore past delays. The logical remedy is to base estimates on how long similar tasks really took; assuming everything will go smoothly is exactly the error described.', 3, false, 5),
  ('bff99ffa-fe74-4ce8-875c-711d2ed5b2cf', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Choose the correct verb forms: ''The minibus ______ along the Addis Ababa–Adama road when one of its tyres ______.''', '[{"key":"A","text":"travelled / was bursting"},{"key":"B","text":"was travelling / burst"},{"key":"C","text":"has travelled / bursts"},{"key":"D","text":"travels / had burst"}]'::jsonb, 'B', 'The past continuous (''was travelling'') describes the longer background action, and the past simple (''burst'') describes the short event that interrupted it.', 1, false, 1),
  ('22341969-e1cc-4127-b994-4f0ab62c9425', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Change the sentence into the passive voice: ''The traffic police questioned the driver after the accident.''', '[{"key":"A","text":"The driver has been questioned by the traffic police after the accident."},{"key":"B","text":"The driver questioned the traffic police after the accident."},{"key":"C","text":"The driver was questioned by the traffic police after the accident."},{"key":"D","text":"The driver was questioning by the traffic police after the accident."}]'::jsonb, 'C', 'In the passive, the object of the active sentence (the driver) becomes the subject, and the past simple ''questioned'' becomes ''was questioned'' (was + past participle). The tense must remain the past simple.', 2, false, 2),
  ('59a6b82d-2e23-42e4-96d2-27606452ed5e', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Choose the correct option: ''By the time the ambulance arrived, the injured passengers ______ out of the car by bystanders.''', '[{"key":"A","text":"have already been pulled"},{"key":"B","text":"had already pulled"},{"key":"C","text":"are already pulled"},{"key":"D","text":"had already been pulled"}]'::jsonb, 'D', '''By the time'' + past simple shows that the action was completed before another past action, so the past perfect is needed. Because the bystanders did the pulling, the passengers receive the action, so the past perfect passive ''had already been pulled'' is correct.', 3, false, 3),
  ('6a3b0506-f19e-4968-862f-4e1d8431ace9', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Read the passage and answer the question. ''Witnesses said the lorry was overtaking on a bend when it met an oncoming bus. The road was dry, visibility was good, and inspectors found that both vehicles were in sound mechanical condition. Investigators later learned that the lorry driver had been driving for fourteen hours without rest.'' Based on the evidence, what was the most likely main cause of the accident?', '[{"key":"A","text":"The lorry driver''s fatigue and unsafe overtaking"},{"key":"B","text":"Poor weather conditions"},{"key":"C","text":"Mechanical failure of the vehicles"},{"key":"D","text":"Poor visibility on the road"}]'::jsonb, 'A', 'The passage rules out weather, visibility and mechanical faults, but reports fourteen hours of driving without rest and overtaking on a bend. The evidence therefore points to driver fatigue leading to unsafe overtaking.', 2, false, 4),
  ('33304ada-73a0-4825-8651-0530c6256df4', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', '35bcfff8-528b-45c7-9b06-74c31ba01c79', 'Put the sentences in the correct order to form a short narrative: (1) An ambulance took her to the hospital. (2) A girl was crossing the road at Mexico Square. (3) Suddenly, a speeding taxi hit her. (4) Fortunately, she recovered within a week.', '[{"key":"A","text":"3, 2, 1, 4"},{"key":"B","text":"2, 1, 3, 4"},{"key":"C","text":"2, 3, 1, 4"},{"key":"D","text":"4, 2, 3, 1"}]'::jsonb, 'C', 'A narrative follows time order: the background (the girl crossing the road), the main event (the taxi hitting her), the response (the ambulance) and the outcome (her recovery). ''Suddenly'' signals the interrupting event and ''Fortunately'' introduces the ending.', 1, false, 5),
  ('56c3f32e-e4ff-4e69-b68f-1949d9882cd7', '31c9b5cc-1575-4385-86cc-d18232834b11', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'A stone is thrown horizontally at 15 m/s from the top of a cliff 20 m high. How long does it take to reach the ground? (g = 10 m/s², ignore air resistance)', '[{"key":"A","text":"1.3 s"},{"key":"B","text":"2 s"},{"key":"C","text":"3 s"},{"key":"D","text":"4 s"}]'::jsonb, 'B', 'The horizontal velocity does not affect the vertical motion, which starts with zero vertical velocity. From h = ½gt²: 20 = ½ × 10 × t², so t² = 4 and t = 2 s.', 1, true, 1),
  ('2edf6639-777b-4274-b5a8-9130ae671984', '31c9b5cc-1575-4385-86cc-d18232834b11', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'A ball is kicked from level ground at 20 m/s at an angle of 30° above the horizontal. What is its horizontal range? (g = 10 m/s², ignore air resistance)', '[{"key":"A","text":"20 m"},{"key":"B","text":"17.3 m"},{"key":"C","text":"40 m"},{"key":"D","text":"34.6 m"}]'::jsonb, 'D', 'R = v₀² sin 2θ / g = (20)² × sin 60° ÷ 10 = 400 × 0.866 ÷ 10 ≈ 34.6 m. A range of 40 m would only be reached at a launch angle of 45°.', 2, true, 2),
  ('c4d6a7c4-e238-4dc5-8382-868ed24a2e8b', '31c9b5cc-1575-4385-86cc-d18232834b11', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'A 0.5 kg stone tied to a string moves in a horizontal circle of radius 2 m on a smooth table at a constant speed of 4 m/s. What is the tension in the string?', '[{"key":"A","text":"4 N"},{"key":"B","text":"1 N"},{"key":"C","text":"8 N"},{"key":"D","text":"16 N"}]'::jsonb, 'A', 'On a smooth horizontal table the tension alone provides the centripetal force: T = mv²/r = 0.5 × 4² ÷ 2 = 8 ÷ 2 = 4 N.', 2, true, 3),
  ('ae618db8-595f-4fc3-a7c3-34145c673627', '31c9b5cc-1575-4385-86cc-d18232834b11', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'Two satellites orbit the Earth. The orbital radius of satellite Q is 4 times that of satellite P. If the period of P is T, what is the period of Q?', '[{"key":"A","text":"2T"},{"key":"B","text":"4T"},{"key":"C","text":"8T"},{"key":"D","text":"16T"}]'::jsonb, 'C', 'By Kepler''s third law, T² is proportional to r³. If r increases 4 times, T² increases 4³ = 64 times, so the period increases √64 = 8 times and Q''s period is 8T.', 3, true, 4),
  ('f93c2bdf-1fc3-4b30-9e26-46aaa92fda2a', '31c9b5cc-1575-4385-86cc-d18232834b11', '6b8c3dd8-fd24-4e2d-b6ae-1d46a93de2c1', 'A student on a freely rotating stool holds two dumbbells at arm''s length and spins at 2 rev/s, with a total moment of inertia of 4.0 kg·m². She pulls the dumbbells to her chest, reducing the moment of inertia to 1.6 kg·m². What is her new rate of rotation?', '[{"key":"A","text":"0.8 rev/s"},{"key":"B","text":"5 rev/s"},{"key":"C","text":"3.2 rev/s"},{"key":"D","text":"6.4 rev/s"}]'::jsonb, 'B', 'With no external torque, angular momentum is conserved: I₁ω₁ = I₂ω₂. So ω₂ = (4.0 × 2) ÷ 1.6 = 5 rev/s; she spins faster because her moment of inertia has decreased.', 2, true, 5),
  ('57be0223-e8f7-4575-b24d-d818170f9f5a', '31c9b5cc-1575-4385-86cc-d18232834b11', '7e60f676-b178-4409-8644-04c21268ad31', 'What is the pressure due to the water alone at a depth of 5 m in Lake Tana? (ρ = 1000 kg/m³, g = 10 m/s²)', '[{"key":"A","text":"50 kPa"},{"key":"B","text":"5 kPa"},{"key":"C","text":"500 kPa"},{"key":"D","text":"0.5 kPa"}]'::jsonb, 'A', 'P = ρgh = 1000 kg/m³ × 10 m/s² × 5 m = 50,000 Pa = 50 kPa. This is the gauge pressure; atmospheric pressure would be added to find the absolute pressure.', 1, false, 1),
  ('6165b005-2089-4d54-9b2b-8e30fd985ccf', '31c9b5cc-1575-4385-86cc-d18232834b11', '7e60f676-b178-4409-8644-04c21268ad31', 'In a hydraulic lift, the small piston has an area of 0.01 m² and the large piston has an area of 0.5 m². What force must be applied to the small piston to lift a car weighing 15,000 N?', '[{"key":"A","text":"750 N"},{"key":"B","text":"300 N"},{"key":"C","text":"150 N"},{"key":"D","text":"3,000 N"}]'::jsonb, 'B', 'By Pascal''s principle the pressure is the same on both pistons: F₁/A₁ = F₂/A₂. So F₁ = 15,000 N × (0.01 ÷ 0.5) = 300 N.', 2, false, 2),
  ('e53cebb9-7946-420d-b04f-6060a66018c8', '31c9b5cc-1575-4385-86cc-d18232834b11', '7e60f676-b178-4409-8644-04c21268ad31', 'A block of wood with a density of 600 kg/m³ floats in water (density 1000 kg/m³). What fraction of its volume is below the water surface?', '[{"key":"A","text":"0.4"},{"key":"B","text":"0.8"},{"key":"C","text":"0.6"},{"key":"D","text":"1.0"}]'::jsonb, 'C', 'For a floating body, weight = buoyant force, so ρ(wood) × V × g = ρ(water) × V(submerged) × g. Therefore V(submerged)/V = 600 ÷ 1000 = 0.6, so 60% of the block is under water.', 2, false, 3),
  ('84ba518c-7a9a-4195-89df-99925eb80ee3', '31c9b5cc-1575-4385-86cc-d18232834b11', '7e60f676-b178-4409-8644-04c21268ad31', 'Water flows through a horizontal pipe. At point 1 the cross-sectional area is 0.02 m², the speed is 2 m/s and the pressure is 1.2 × 10⁵ Pa. At point 2 the area narrows to 0.01 m². What is the pressure at point 2? (ρ = 1000 kg/m³)', '[{"key":"A","text":"1.26 × 10⁵ Pa"},{"key":"B","text":"1.20 × 10⁵ Pa"},{"key":"C","text":"1.08 × 10⁵ Pa"},{"key":"D","text":"1.14 × 10⁵ Pa"}]'::jsonb, 'D', 'Continuity gives v₂ = A₁v₁/A₂ = (0.02 × 2) ÷ 0.01 = 4 m/s. Bernoulli''s equation for a horizontal pipe gives P₂ = P₁ + ½ρ(v₁² − v₂²) = 1.2 × 10⁵ + ½ × 1000 × (4 − 16) = 1.2 × 10⁵ − 6,000 = 1.14 × 10⁵ Pa.', 3, false, 4),
  ('d6cd6c4a-7292-4af5-85f7-00f8a882b783', '31c9b5cc-1575-4385-86cc-d18232834b11', '7e60f676-b178-4409-8644-04c21268ad31', 'A metal block weighs 30 N in air and 20 N when fully submerged in water. What is the density of the metal? (density of water = 1000 kg/m³, g = 10 m/s²)', '[{"key":"A","text":"1,500 kg/m³"},{"key":"B","text":"2,000 kg/m³"},{"key":"C","text":"3,000 kg/m³"},{"key":"D","text":"667 kg/m³"}]'::jsonb, 'C', 'Buoyant force = 30 N − 20 N = 10 N = ρ(water) × V × g, so V = 10 ÷ (1000 × 10) = 1.0 × 10⁻³ m³. The mass is 30 ÷ 10 = 3 kg, so the density is 3 kg ÷ (1.0 × 10⁻³ m³) = 3,000 kg/m³.', 2, false, 5),
  ('5648dabc-cefb-48cd-931d-9aefd5e1c836', '31c9b5cc-1575-4385-86cc-d18232834b11', '5a75ce5a-97fc-434f-978e-261af116085d', 'A straight wire 0.5 m long carries a current of 4 A at right angles to a uniform magnetic field of 0.2 T. What is the magnitude of the force on the wire?', '[{"key":"A","text":"0.1 N"},{"key":"B","text":"1.6 N"},{"key":"C","text":"0.4 N"},{"key":"D","text":"10 N"}]'::jsonb, 'C', 'F = BIL sin θ = 0.2 T × 4 A × 0.5 m × sin 90° = 0.4 N.', 1, false, 1),
  ('76d286e1-2c22-44a4-a98e-19caab062d67', '31c9b5cc-1575-4385-86cc-d18232834b11', '5a75ce5a-97fc-434f-978e-261af116085d', 'The magnetic flux through each turn of a 200-turn coil decreases from 0.05 Wb to 0.01 Wb in 0.2 s. What is the magnitude of the average induced emf?', '[{"key":"A","text":"40 V"},{"key":"B","text":"8 V"},{"key":"C","text":"0.04 V"},{"key":"D","text":"200 V"}]'::jsonb, 'A', 'By Faraday''s law, emf = N × ΔΦ/Δt = 200 × (0.05 − 0.01) Wb ÷ 0.2 s = 200 × 0.04 ÷ 0.2 = 40 V.', 2, false, 2),
  ('4d8132d4-c8ef-42ab-9668-7af521a24305', '31c9b5cc-1575-4385-86cc-d18232834b11', '5a75ce5a-97fc-434f-978e-261af116085d', 'The north pole of a bar magnet is pushed towards one end of a coil connected to a galvanometer. According to Lenz''s law, the induced current will:', '[{"key":"A","text":"make the near end of the coil a south pole, attracting the magnet"},{"key":"B","text":"be zero, because the magnet itself carries no current"},{"key":"C","text":"start only after the magnet has stopped moving"},{"key":"D","text":"make the near end of the coil a north pole, opposing the motion of the magnet"}]'::jsonb, 'D', 'Lenz''s law states that the induced current flows so as to oppose the change that produces it. As the north pole approaches, the near end of the coil becomes a north pole and repels the magnet, so work must be done to push it in, which is consistent with conservation of energy.', 2, false, 3),
  ('61d58b50-0576-401f-acdc-95ea43e2601a', '31c9b5cc-1575-4385-86cc-d18232834b11', '5a75ce5a-97fc-434f-978e-261af116085d', 'A step-down transformer converts 220 V mains to 11 V for a phone charger. If the primary coil has 1,000 turns, how many turns does the secondary coil have? (Assume an ideal transformer.)', '[{"key":"A","text":"50"},{"key":"B","text":"20"},{"key":"C","text":"200"},{"key":"D","text":"20,000"}]'::jsonb, 'A', 'For an ideal transformer, Vₛ/Vₚ = Nₛ/Nₚ, so Nₛ = 1,000 × 11 ÷ 220 = 50 turns.', 1, false, 4),
  ('01c50e8a-5003-47fd-bd4e-729889abd3c7', '31c9b5cc-1575-4385-86cc-d18232834b11', '5a75ce5a-97fc-434f-978e-261af116085d', 'A power station sends 10 MW of electrical power through transmission lines of total resistance 5 Ω at a voltage of 100 kV. How much power is lost as heat in the lines?', '[{"key":"A","text":"5 kW"},{"key":"B","text":"50 kW"},{"key":"C","text":"500 kW"},{"key":"D","text":"5 MW"}]'::jsonb, 'B', 'The current in the lines is I = P/V = (10 × 10⁶ W) ÷ (100 × 10³ V) = 100 A. The power lost is I²R = 100² × 5 = 50,000 W = 50 kW, only 0.5% of the power sent.', 3, false, 5),
  ('81096d74-0a5c-4044-9c41-d2689610be09', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'What is the pH of a 0.001 M HCl solution at 25 °C?', '[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"11"},{"key":"D","text":"0.001"}]'::jsonb, 'B', 'HCl is a strong acid and ionizes completely, so [H⁺] = 0.001 M = 1 × 10⁻³ M. pH = −log(1 × 10⁻³) = 3.', 1, true, 1),
  ('14ef740d-f14e-4f96-a400-61c84126c4c5', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'Which of the following can act as a Lewis acid but NOT as a Brønsted–Lowry acid?', '[{"key":"A","text":"HCl"},{"key":"B","text":"NH₄⁺"},{"key":"C","text":"H₂O"},{"key":"D","text":"BF₃"}]'::jsonb, 'D', 'BF₃ has only six valence electrons around boron, so it can accept an electron pair (Lewis acid), but it has no H⁺ to donate. HCl, NH₄⁺ and H₂O can all donate a proton, so they are also Brønsted–Lowry acids.', 2, true, 2),
  ('7276093f-01bd-4f1a-9cbd-64797a302bbf', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'What is the pH of a 0.10 M acetic acid solution? (Ka = 1.8 × 10⁻⁵)', '[{"key":"A","text":"2.87"},{"key":"B","text":"1.00"},{"key":"C","text":"4.74"},{"key":"D","text":"5.74"}]'::jsonb, 'A', 'For a weak acid, [H⁺] ≈ √(Ka × C) = √(1.8 × 10⁻⁵ × 0.10) = √(1.8 × 10⁻⁶) ≈ 1.34 × 10⁻³ M. So pH = −log(1.34 × 10⁻³) ≈ 2.87.', 2, true, 3),
  ('f07b3f36-9660-4d09-be0b-55a422110f9a', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'A buffer solution contains 0.10 M acetic acid and 0.20 M sodium acetate. What is its pH? (pKa of acetic acid = 4.74, log 2 = 0.30)', '[{"key":"A","text":"4.44"},{"key":"B","text":"4.74"},{"key":"C","text":"5.04"},{"key":"D","text":"9.26"}]'::jsonb, 'C', 'By the Henderson–Hasselbalch equation, pH = pKa + log([CH₃COO⁻]/[CH₃COOH]) = 4.74 + log(0.20/0.10) = 4.74 + 0.30 = 5.04.', 3, true, 4),
  ('39268264-87bc-4a9a-b995-bde72d8ebb1d', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '4f7805d5-4824-4da5-af8d-f35e1cf0e5c5', 'Which of the following 0.1 M aqueous solutions has a pH greater than 7?', '[{"key":"A","text":"NaCl"},{"key":"B","text":"NH₄Cl"},{"key":"C","text":"KNO₃"},{"key":"D","text":"CH₃COONa"}]'::jsonb, 'D', 'CH₃COONa is the salt of a weak acid and a strong base, so the acetate ion hydrolyzes (CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻) and makes the solution basic. NaCl and KNO₃ give neutral solutions, and NH₄Cl gives an acidic one.', 2, true, 5),
  ('07aee77e-7ed9-4c9d-b113-7e86fdbaa455', '15d0f3e0-4a95-4428-b43e-c49216775d7f', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'What is the oxidation number of manganese in potassium permanganate, KMnO₄?', '[{"key":"A","text":"+7"},{"key":"B","text":"+2"},{"key":"C","text":"+4"},{"key":"D","text":"+6"}]'::jsonb, 'A', 'The compound is neutral, so (+1) + x + 4(−2) = 0, which gives x = +7 for manganese.', 1, false, 1),
  ('d0bf4e57-e933-4548-b566-5a8e1afb9a41', '15d0f3e0-4a95-4428-b43e-c49216775d7f', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'For the cell Zn | Zn²⁺ || Cu²⁺ | Cu, the standard reduction potentials are E°(Zn²⁺/Zn) = −0.76 V and E°(Cu²⁺/Cu) = +0.34 V. What is the standard cell potential?', '[{"key":"A","text":"−1.10 V"},{"key":"B","text":"+0.42 V"},{"key":"C","text":"+1.10 V"},{"key":"D","text":"−0.42 V"}]'::jsonb, 'C', 'E°cell = E°(cathode) − E°(anode) = +0.34 V − (−0.76 V) = +1.10 V. Copper(II) ions are reduced at the cathode and zinc is oxidized at the anode.', 2, false, 2),
  ('f1faec64-03a7-4715-ba7b-8e900e958588', '15d0f3e0-4a95-4428-b43e-c49216775d7f', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'Given E°(Ag⁺/Ag) = +0.80 V and E°(Cu²⁺/Cu) = +0.34 V, which reaction is spontaneous under standard conditions?', '[{"key":"A","text":"2Ag + Cu²⁺ → 2Ag⁺ + Cu"},{"key":"B","text":"Cu + 2Ag⁺ → Cu²⁺ + 2Ag"},{"key":"C","text":"Both reactions are spontaneous"},{"key":"D","text":"Neither reaction is spontaneous"}]'::jsonb, 'B', 'In Cu + 2Ag⁺ → Cu²⁺ + 2Ag, silver ions are reduced and copper is oxidized, so E°cell = 0.80 − 0.34 = +0.46 V. A positive E°cell means this reaction is spontaneous, while the reverse reaction (E°cell = −0.46 V) is not.', 2, false, 3),
  ('51e5f4d6-9c77-4048-abd6-ce3d8b51e90e', '15d0f3e0-4a95-4428-b43e-c49216775d7f', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'A current of 2.0 A is passed through aqueous CuSO₄ for 965 s. What mass of copper is deposited at the cathode? (Cu = 63.5 g/mol, F = 96,500 C/mol)', '[{"key":"A","text":"0.318 g"},{"key":"B","text":"1.27 g"},{"key":"C","text":"6.35 g"},{"key":"D","text":"0.635 g"}]'::jsonb, 'D', 'Charge Q = It = 2.0 A × 965 s = 1,930 C, which is 1,930 ÷ 96,500 = 0.020 mol of electrons. Since Cu²⁺ + 2e⁻ → Cu, 0.010 mol of Cu forms: 0.010 × 63.5 = 0.635 g.', 3, false, 4),
  ('0654acda-2f8c-44f4-8e42-8ed8e89dad47', '15d0f3e0-4a95-4428-b43e-c49216775d7f', 'fef8aaf8-7e40-4243-89ab-496d7434cd28', 'During the electrolysis of concentrated aqueous sodium chloride (brine) with inert electrodes, what are the main products at the cathode and the anode?', '[{"key":"A","text":"Sodium at the cathode and chlorine at the anode"},{"key":"B","text":"Hydrogen at the cathode and oxygen at the anode"},{"key":"C","text":"Hydrogen at the cathode and chlorine at the anode"},{"key":"D","text":"Chlorine at the cathode and hydrogen at the anode"}]'::jsonb, 'C', 'At the cathode water is reduced in preference to Na⁺ (2H₂O + 2e⁻ → H₂ + 2OH⁻), so hydrogen forms. At the anode the concentrated Cl⁻ ions are oxidized to Cl₂, and sodium hydroxide is left in solution.', 3, false, 5),
  ('2cb5424d-f7ea-4096-b3e6-22da3d74a237', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'Which catalyst is used in the Haber process for manufacturing ammonia?', '[{"key":"A","text":"Vanadium(V) oxide"},{"key":"B","text":"Iron"},{"key":"C","text":"Platinum–rhodium gauze"},{"key":"D","text":"Nickel"}]'::jsonb, 'B', 'The Haber process (N₂ + 3H₂ ⇌ 2NH₃) uses a finely divided iron catalyst. Vanadium(V) oxide is used in the Contact process, platinum–rhodium in the Ostwald process and nickel in hydrogenating vegetable oils.', 1, false, 1),
  ('bcfe46f5-8a54-4624-b4d0-1698bc70e765', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'For the Haber process, N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH = −92 kJ/mol. Which change increases the equilibrium yield of ammonia?', '[{"key":"A","text":"Increasing the temperature"},{"key":"B","text":"Decreasing the pressure"},{"key":"C","text":"Adding more catalyst"},{"key":"D","text":"Increasing the pressure"}]'::jsonb, 'D', 'The forward reaction reduces 4 moles of gas to 2, so raising the pressure shifts the equilibrium to the right (Le Chatelier''s principle). Raising the temperature favours the endothermic reverse reaction, and a catalyst only helps equilibrium be reached faster without changing the yield.', 2, false, 2),
  ('93a5d0bd-e065-4164-bfdd-be4893971ce7', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'In the Contact process, SO₃ is absorbed in concentrated sulfuric acid to form oleum (H₂S₂O₇) instead of being dissolved directly in water. Why?', '[{"key":"A","text":"SO₃ does not react with water at all"},{"key":"B","text":"Oleum is the final product needed by all industries"},{"key":"C","text":"Dissolving SO₃ directly in water is violently exothermic and forms a corrosive acid mist"},{"key":"D","text":"Water would poison the vanadium(V) oxide catalyst"}]'::jsonb, 'C', 'SO₃ reacts with water so exothermically that a fine mist of sulfuric acid droplets forms, which is hard to condense and dangerous. Absorbing SO₃ in concentrated H₂SO₄ to make oleum and then diluting the oleum with water gives sulfuric acid safely.', 2, false, 3),
  ('9d1f6cb4-4525-4dad-961c-006ad87a4b95', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'In an ammonia plant, 28 tonnes of nitrogen react with excess hydrogen: N₂ + 3H₂ ⇌ 2NH₃. If the percentage yield is 15%, what mass of ammonia is obtained? (N = 14, H = 1)', '[{"key":"A","text":"5.1 tonnes"},{"key":"B","text":"4.2 tonnes"},{"key":"C","text":"15 tonnes"},{"key":"D","text":"34 tonnes"}]'::jsonb, 'A', 'From the equation, 1 mol N₂ (28 g) gives 2 mol NH₃ (2 × 17 = 34 g), so 28 tonnes of N₂ could give 34 tonnes of NH₃. At 15% yield the actual mass is 0.15 × 34 = 5.1 tonnes.', 3, false, 4),
  ('deea0b29-5416-4494-ae80-1fb2196718de', '15d0f3e0-4a95-4428-b43e-c49216775d7f', '3b482a4e-f89b-48d5-8b66-99e88b5ea4e7', 'Ethiopia produces large amounts of cement for its construction industry. Which raw materials are heated together in a rotary kiln to make Portland cement clinker?', '[{"key":"A","text":"Limestone and clay (or shale)"},{"key":"B","text":"Sand and soda ash"},{"key":"C","text":"Bauxite and cryolite"},{"key":"D","text":"Iron ore and coke"}]'::jsonb, 'A', 'Portland cement is made by heating limestone (CaCO₃) with clay or shale in a rotary kiln at about 1,450 °C to form clinker, which is then ground with a little gypsum. Sand and soda ash are used for glass, bauxite and cryolite for aluminium, and iron ore and coke for iron.', 1, false, 5),
  ('cb6828a0-0e86-4d29-9645-3dfd82aa904e', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'Which of the following structures is NOT found in a typical bacterial cell?', '[{"key":"A","text":"Cell wall"},{"key":"B","text":"Ribosomes"},{"key":"C","text":"Plasma membrane"},{"key":"D","text":"A membrane-bound nucleus"}]'::jsonb, 'D', 'Bacteria are prokaryotes: their DNA lies in the cytoplasm in a region called the nucleoid, with no nuclear membrane. They do have a cell wall, a plasma membrane and (70S) ribosomes.', 1, true, 1),
  ('4be33118-cb46-4936-ae8c-7976cb734e49', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'A bacterium divides by binary fission every 20 minutes. Starting from a single cell under ideal conditions, how many cells will there be after 2 hours?', '[{"key":"A","text":"12"},{"key":"B","text":"64"},{"key":"C","text":"32"},{"key":"D","text":"128"}]'::jsonb, 'B', '2 hours = 120 minutes, which is 120 ÷ 20 = 6 generations. The population doubles each generation, so N = 1 × 2⁶ = 64 cells.', 2, true, 2),
  ('fc6b022e-9d97-4cc1-a345-8aff130f3a41', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'In Gram staining, Gram-positive bacteria stay purple while Gram-negative bacteria appear pink. What causes this difference?', '[{"key":"A","text":"Gram-positive bacteria have a thick peptidoglycan wall that retains the crystal violet–iodine complex"},{"key":"B","text":"Gram-negative bacteria have no cell wall at all"},{"key":"C","text":"Gram-positive bacteria have an outer lipid membrane that traps the purple dye"},{"key":"D","text":"Gram-negative bacteria contain more DNA, which absorbs the pink safranin"}]'::jsonb, 'A', 'The thick peptidoglycan layer of Gram-positive cells traps the crystal violet–iodine complex when alcohol is applied, so they stay purple. Gram-negative cells have a thin peptidoglycan layer and an outer membrane, so they lose the purple dye and take up the pink safranin counterstain.', 3, true, 3),
  ('bc9df16a-ce49-4b44-8a02-e433aeb91996', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'Antibiotics such as penicillin do not cure viral infections such as influenza because viruses:', '[{"key":"A","text":"have thick cell walls that antibiotics cannot penetrate"},{"key":"B","text":"reproduce too slowly for antibiotics to act"},{"key":"C","text":"lack the cell walls and ribosomes that antibiotics target, and multiply using the host cell''s machinery"},{"key":"D","text":"are much larger than bacteria"}]'::jsonb, 'C', 'Antibiotics act on bacterial structures and processes, such as peptidoglycan cell walls and 70S ribosomes. Viruses have neither; they multiply inside host cells using the host''s machinery, so antibiotics have nothing to act on.', 2, true, 4),
  ('0dc83d04-aaa2-4b8e-acb0-39c905eb01ac', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'dcedf30e-b72e-4ea3-a96f-2148b47d228e', 'Rhizobium bacteria live in the root nodules of legumes such as faba bean and chickpea. Why are they important to Ethiopian farmers?', '[{"key":"A","text":"They convert atmospheric nitrogen (N₂) into ammonia that the plant can use"},{"key":"B","text":"They convert nitrates in the soil back into nitrogen gas"},{"key":"C","text":"They carry out photosynthesis for the plant"},{"key":"D","text":"They produce antibiotics that kill all other soil bacteria"}]'::jsonb, 'A', 'Rhizobium fixes atmospheric nitrogen (N₂) into ammonia, which the legume uses to make proteins, while the plant supplies the bacteria with sugars. This enriches the soil with nitrogen and reduces the need for chemical fertilizer, which is why legumes are rotated with cereals.', 2, true, 5),
  ('3b011398-785b-4139-8f37-0464b47d44da', '2f6ec046-2874-4405-8b1b-62ae239bbb77', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'Where in the chloroplast do the light-dependent reactions of photosynthesis take place?', '[{"key":"A","text":"Stroma"},{"key":"B","text":"Outer membrane"},{"key":"C","text":"Thylakoid membranes"},{"key":"D","text":"Matrix"}]'::jsonb, 'C', 'The light-dependent reactions take place on the thylakoid membranes, where chlorophyll and the electron transport chain are located. The Calvin cycle occurs in the stroma, and the matrix is part of the mitochondrion.', 1, false, 1),
  ('934923b1-1aa5-4e45-bd16-498d1239d9e7', '2f6ec046-2874-4405-8b1b-62ae239bbb77', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'The oxygen gas released during photosynthesis comes from which molecule?', '[{"key":"A","text":"Carbon dioxide"},{"key":"B","text":"Glucose"},{"key":"C","text":"RuBP"},{"key":"D","text":"Water"}]'::jsonb, 'D', 'During photolysis in the light-dependent reactions, water is split: 2H₂O → 4H⁺ + 4e⁻ + O₂. Experiments with the oxygen isotope ¹⁸O showed that the O₂ released comes from water, not from CO₂.', 2, false, 2),
  ('64b64670-9dda-4e8c-b875-2693801c4573', '2f6ec046-2874-4405-8b1b-62ae239bbb77', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'Where does glycolysis take place, and what is its net ATP yield per molecule of glucose?', '[{"key":"A","text":"Cytoplasm; net 2 ATP"},{"key":"B","text":"Mitochondrial matrix; net 2 ATP"},{"key":"C","text":"Cytoplasm; net 4 ATP"},{"key":"D","text":"Inner mitochondrial membrane; net 34 ATP"}]'::jsonb, 'A', 'Glycolysis occurs in the cytoplasm, where glucose is split into two pyruvate molecules. It produces 4 ATP but uses 2, giving a net gain of 2 ATP (plus 2 NADH).', 2, false, 3),
  ('40b9732e-f7c3-4895-8d31-177b9d069e53', '2f6ec046-2874-4405-8b1b-62ae239bbb77', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'Near the end of a 10,000 m race, an Ethiopian athlete''s leg muscles produce lactate. Which statement best explains this?', '[{"key":"A","text":"Lactate is made because it yields more ATP than aerobic respiration"},{"key":"B","text":"Oxygen supply cannot keep up with demand, so pyruvate is reduced to lactate to regenerate NAD⁺ and keep glycolysis running"},{"key":"C","text":"The Krebs cycle converts glucose directly into lactate"},{"key":"D","text":"The muscles have run out of glucose, so they make lactate from fat instead"}]'::jsonb, 'B', 'When oxygen cannot be supplied fast enough, the electron transport chain slows and NAD⁺ is not regenerated. Reducing pyruvate to lactate regenerates NAD⁺ so glycolysis can continue, although it yields only 2 ATP per glucose.', 3, false, 4),
  ('e0001907-57f8-404b-bcb2-b4b47589ed9c', '2f6ec046-2874-4405-8b1b-62ae239bbb77', '220c0eb1-b29c-4483-af05-b5bf97ece207', 'In the Calvin cycle of C3 plants such as wheat, what is the first stable product formed when CO₂ is fixed?', '[{"key":"A","text":"Glucose"},{"key":"B","text":"Oxaloacetate"},{"key":"C","text":"Pyruvate"},{"key":"D","text":"3-phosphoglycerate (PGA)"}]'::jsonb, 'D', 'RuBisCO joins CO₂ to the 5-carbon RuBP, forming an unstable 6-carbon compound that immediately splits into two molecules of 3-phosphoglycerate (PGA). Oxaloacetate is the first product in C4 plants such as maize and sugarcane.', 3, false, 5),
  ('99947d02-0cc3-470b-bf99-f1fd1bf38f34', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'Which pair consists of homologous structures?', '[{"key":"A","text":"Wing of a bird and wing of a butterfly"},{"key":"B","text":"Eye of an octopus and eye of a human"},{"key":"C","text":"Spines of a cactus and quills of a porcupine"},{"key":"D","text":"Forelimb of a human and flipper of a whale"}]'::jsonb, 'D', 'The human forelimb and the whale flipper share the same basic bone pattern (humerus, radius, ulna, carpals and phalanges) inherited from a common ancestor, even though they are used differently. The other pairs are analogous: they serve similar functions but evolved independently.', 1, false, 1),
  ('81859b99-ac13-4db0-9524-900b276b87b6', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'Which statement reflects Lamarck''s idea rather than Darwin''s?', '[{"key":"A","text":"Individuals with favourable variations are more likely to survive and reproduce."},{"key":"B","text":"Giraffes got long necks because each generation stretched to reach high leaves and passed the longer necks on to their offspring."},{"key":"C","text":"More offspring are produced than can survive."},{"key":"D","text":"Members of a population vary in their traits."}]'::jsonb, 'B', 'Lamarck proposed that characteristics acquired during an organism''s life through use and disuse are passed on to offspring, as in the stretching giraffe. The other three statements are parts of Darwin''s theory of natural selection.', 2, false, 2),
  ('05ad4034-fc49-44fa-9f99-c50c40d42802', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'The famous fossil Lucy, discovered in 1974 at Hadar in the Afar region of Ethiopia, belongs to which species?', '[{"key":"A","text":"Australopithecus afarensis"},{"key":"B","text":"Homo sapiens"},{"key":"C","text":"Homo erectus"},{"key":"D","text":"Ardipithecus ramidus"}]'::jsonb, 'A', 'Lucy is a partial skeleton of Australopithecus afarensis, about 3.2 million years old. Her pelvis and leg bones show that she walked upright, making her important evidence for early bipedalism.', 1, false, 3),
  ('2c7d051c-5809-418b-bde4-8fa290216935', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'In parts of Africa where malaria is common, the sickle-cell allele (HbS) stays at a relatively high frequency even though people with the genotype HbS HbS often die young. Which statement best explains this?', '[{"key":"A","text":"The HbS allele is dominant over the normal allele"},{"key":"B","text":"Mutation recreates the HbS allele at a high rate in every generation"},{"key":"C","text":"Heterozygous carriers (HbA HbS) resist malaria better than HbA HbA individuals, so they survive and reproduce more"},{"key":"D","text":"Malaria parasites cause the HbS mutation in red blood cells"}]'::jsonb, 'C', 'This is heterozygote advantage, a form of balancing selection: carriers have only mild symptoms but are more resistant to severe malaria, so in malarial regions they have the highest fitness. Their survival keeps the HbS allele in the population even though HbS HbS individuals are selected against.', 3, false, 4),
  ('a351da62-b2e7-42f7-99d4-59360975bf5d', '2f6ec046-2874-4405-8b1b-62ae239bbb77', 'ab83e9b1-c718-4a1c-90d5-664e1695200f', 'Two populations of the same species become separated by a mountain range. After many generations they can no longer interbreed, even when brought together. This is an example of:', '[{"key":"A","text":"Sympatric speciation"},{"key":"B","text":"Allopatric speciation"},{"key":"C","text":"Convergent evolution"},{"key":"D","text":"Artificial selection"}]'::jsonb, 'B', 'Allopatric speciation occurs when a geographical barrier separates populations, and different mutations and selection pressures then make them reproductively isolated. Sympatric speciation occurs without geographical separation.', 2, false, 5)
